sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float zoom;
uniform float sizing;
uniform float offset;
uniform float mirror;
uniform float vertical;
uniform float angle;
half4 pick(float2 s, bool turned) {
    if (!turned) return image.eval(s);
    float3 g = fromLayer * float3(s, 1.0);
    return image.eval(g.xy / g.z);
}
half4 main(float2 coord) {
    bool turned = abs(fromLayer[0].y) + abs(fromLayer[1].x) + abs(fromLayer[0].z) + abs(fromLayer[1].z) > 0.0001;
    float2 q = coord;
    float2 full = size;
    if (turned) {
        float3 w = toLayer * float3(coord, 1.0);
        if (w.z <= 0.0) return half4(0);
        q = w.xy / w.z;
        full = layer;
    }
    float2 c = full * 0.5;
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 p = q - c;
    float2 box = max(full, float2(1.0));
    if (sizing > 1.5) {
        float2 h = p / box + 0.5;
        if (vertical > 0.5) h.y -= offset * floor(h.x);
        else h.x -= offset * floor(h.y);
        float2 m = floor(h);
        float2 u = h - m;
        if (mirror > 0.5) u = mix(u, 1.0 - u, mod(m, 2.0));
        float2 l = (u - 0.5) * box;
        float2 s = float2(cs * l.x + sn * l.y, -sn * l.x + cs * l.y) / max(zoom, 0.005) + c;
        if (s.x < 0.0 || s.y < 0.0 || s.x > full.x || s.y > full.y) return half4(0);
        return pick(clamp(s, float2(0.5), full - 0.5), turned);
    }
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y);
    if (sizing > 0.5) p /= max(zoom, 0.005);
    else p *= max(zoom, 0.005);
    float2 g = p / box + 0.5;
    if (vertical > 0.5) g.y -= offset * floor(g.x);
    else g.x -= offset * floor(g.y);
    float2 n = floor(g);
    float2 t = g - n;
    if (mirror > 0.5) t = mix(t, 1.0 - t, mod(n, 2.0));
    return pick(clamp(t * full, float2(0.5), full - 0.5), turned);
}
